:root {
  --ink: #060a0b;
  --paper: #e8e0c8;
  --cream: #f2ead2;
  --red: #d72b32;
  --red-hot: #ff3d43;
  --teal: #2f7f7d;
  --blue: #37a7d8;
  --yellow: #f0c24b;
  --panel: rgba(6, 12, 13, 0.78);
  --line: rgba(232, 224, 200, 0.2);
  --display: Impact, Haettenschweiler, "Arial Narrow Bold", "Franklin Gothic Condensed", sans-serif;
  --mono: "Courier New", Courier, monospace;
  --body: "Trebuchet MS", "Gill Sans", sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--body);
  -webkit-user-select: none;
  user-select: none;
  overscroll-behavior: none;
}

button { font: inherit; color: inherit; }

#app { position: fixed; inset: 0; overflow: hidden; background: #05090a; }

#game { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }

.hidden { display: none !important; }

.fx-layer { position: absolute; inset: 0; pointer-events: none; z-index: 5; }
.grain {
  position: absolute; inset: -50%; opacity: .11; mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.9'/%3E%3C/svg%3E");
  animation: grainShift .28s steps(2) infinite;
}
@keyframes grainShift {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-2%, 1%); }
  50% { transform: translate(1%, -2%); }
  75% { transform: translate(2%, 2%); }
  100% { transform: translate(-1%, -1%); }
}
.vignette {
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at center, transparent 35%, rgba(0,0,0,.26) 72%, rgba(0,0,0,.72) 100%);
}
.alarm-flash { position: absolute; inset: 0; opacity: 0; background: radial-gradient(circle at 50% 45%, transparent 30%, rgba(210, 12, 18, .32) 100%); transition: opacity .4s; }
.alarm-flash.on { animation: alarmPulse 1.15s ease-in-out infinite; }
@keyframes alarmPulse { 0%,100% { opacity: .06; } 50% { opacity: .62; } }
.damage-flash { position: absolute; inset: 0; background: #8f0808; opacity: 0; }

/* ---------- HUD ---------- */
.hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
.hud-brand {
  position: absolute; top: max(22px, env(safe-area-inset-top)); left: max(26px, env(safe-area-inset-left));
  display: flex; align-items: center; gap: 11px; opacity: .82;
  filter: drop-shadow(0 2px 8px #000);
}
.brand-mark {
  width: 36px; height: 36px; border: 2px solid var(--cream); border-radius: 50%;
  display: grid; place-items: center; font: 900 25px/1 var(--display); color: var(--red);
  background: radial-gradient(circle at 35% 30%, #fff4d6, #baa88a); box-shadow: inset 0 0 0 3px #2d342d;
}
.brand-title { font: 700 12px/1 var(--mono); letter-spacing: 4px; }
.brand-sub { font: 9px/1.6 var(--mono); letter-spacing: 1.2px; opacity: .55; }

.objective-panel {
  position: absolute; top: max(78px, calc(env(safe-area-inset-top) + 70px)); left: max(27px, env(safe-area-inset-left));
  max-width: 310px; padding-left: 13px; border-left: 3px solid var(--red);
  text-shadow: 0 2px 8px #000; transition: opacity .3s;
}
.objective-label { font: 700 9px/1.2 var(--mono); letter-spacing: 2.2px; color: var(--red-hot); margin-bottom: 6px; }
.objective-text { font: 400 23px/1 var(--display); letter-spacing: 1.4px; color: #f5efd9; }
.objective-detail { font: 11px/1.4 var(--mono); color: rgba(238,230,207,.62); margin-top: 6px; }

.status-panel {
  position: absolute; top: max(22px, env(safe-area-inset-top)); right: max(26px, env(safe-area-inset-right));
  text-align: right; text-shadow: 0 2px 8px #000;
}
.fuse-row { display: flex; align-items: center; justify-content: flex-end; gap: 8px; }
.status-caption { font: 700 9px/1 var(--mono); letter-spacing: 2px; color: rgba(238,230,207,.6); margin-right: 3px; }
.fuse-dot {
  width: 15px; height: 22px; border: 1px solid rgba(238,230,207,.34); border-radius: 8px;
  position: relative; background: rgba(4,10,10,.66); transition: all .35s;
}
.fuse-dot::after { content:""; position: absolute; left: 50%; top: 3px; width: 3px; height: 14px; transform: translateX(-50%); border-radius: 2px; background: rgba(238,230,207,.13); }
.fuse-dot.filled { border-color: #7be2b9; box-shadow: 0 0 14px rgba(104, 255, 183, .5); }
.fuse-dot.filled::after { background: linear-gradient(#eafff6, #47d495); box-shadow: 0 0 8px #52e8a9; }
.tape-row { margin-top: 11px; font: 9px/1 var(--mono); letter-spacing: 1.4px; color: rgba(238,230,207,.51); }
.tape-icon { color: var(--yellow); margin-right: 4px; }

.crosshair {
  position: absolute; left: 50%; top: 50%; width: 18px; height: 18px; transform: translate(-50%, -50%);
  opacity: .7; transition: transform .15s, opacity .15s, filter .15s;
}
.crosshair::before, .crosshair::after { content: ""; position: absolute; background: rgba(245,238,216,.8); box-shadow: 0 0 4px #000; }
.crosshair::before { left: 50%; top: 0; width: 1px; height: 5px; transform: translateX(-50%); }
.crosshair::after { top: 50%; left: 0; height: 1px; width: 5px; transform: translateY(-50%); }
.crosshair i { position: absolute; inset: 8px; border-radius: 50%; background: rgba(245,238,216,.72); }
.crosshair.hot { transform: translate(-50%,-50%) scale(1.5); opacity: 1; filter: drop-shadow(0 0 5px #fff); }
.crosshair.hot::before, .crosshair.hot::after { background: #fff; }

.interact {
  position: absolute; left: 50%; top: calc(50% + 33px); transform: translateX(-50%);
  display: flex; align-items: center; gap: 8px; font: 700 10px/1 var(--mono); letter-spacing: 1.6px;
  color: #f6efd9; background: rgba(3,8,9,.72); border: 1px solid rgba(240,228,195,.18);
  padding: 8px 12px 8px 8px; border-radius: 3px; opacity: 0; transition: opacity .15s, transform .15s;
  backdrop-filter: blur(5px); white-space: nowrap;
}
.interact.show { opacity: 1; transform: translateX(-50%) translateY(-2px); }
.key {
  display: grid; place-items: center; min-width: 22px; height: 22px; padding: 0 5px;
  border: 1px solid rgba(240,228,195,.5); border-radius: 2px; background: #e6dcc0; color: #141b1b;
  font: 900 12px/1 var(--mono); box-shadow: 0 1px 0 rgba(0,0,0,.4);
}

.stamina-wrap {
  position: absolute; left: 50%; bottom: 58px; width: 190px; transform: translateX(-50%);
  opacity: 0; transition: opacity .3s;
}
.stamina-wrap.show { opacity: .85; }
.stamina-label { font: 8px/1 var(--mono); letterspacing: 2px; letter-spacing: 2px; margin-bottom: 5px; text-align: center; color: rgba(238,230,207,.6); }
.stamina-track { height: 3px; background: rgba(255,255,255,.14); overflow: hidden; }
.stamina-fill { height: 100%; width: 100%; background: linear-gradient(90deg, #76d6b1, #d9e88c); transition: width .08s linear; }

.hint {
  position: absolute; bottom: max(20px, env(safe-area-inset-bottom)); left: 50%; transform: translateX(-50%);
  display: flex; gap: 20px; font: 8px/1 var(--mono); letter-spacing: .8px; color: rgba(235,227,204,.38); white-space: nowrap;
}
.hint b { color: rgba(235,227,204,.72); font-weight: 700; }

.subtitle {
  position: absolute; left: 50%; bottom: max(100px, calc(env(safe-area-inset-bottom) + 86px)); transform: translateX(-50%);
  width: min(740px, 82vw); text-align: center; font: 15px/1.55 var(--mono); letter-spacing: .3px;
  color: #f7edce; text-shadow: 0 2px 5px #000, 0 0 24px #000; opacity: 0; transition: opacity .4s;
}
.subtitle.show { opacity: 1; }
.subtitle .who { color: var(--red-hot); font-weight: 700; letter-spacing: 1.4px; }

.toast {
  position: absolute; left: 50%; top: 24%; transform: translate(-50%, -10px);
  padding: 12px 20px; border-top: 1px solid rgba(241,227,194,.36); border-bottom: 1px solid rgba(241,227,194,.36);
  background: linear-gradient(90deg, transparent, rgba(3,8,9,.8) 18%, rgba(3,8,9,.8) 82%, transparent);
  font: 700 11px/1 var(--mono); letter-spacing: 2.2px; color: #f4ebd2; opacity: 0;
  transition: opacity .35s, transform .35s; white-space: nowrap; text-align: center;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast.warn { color: #ff8a84; border-color: rgba(255,66,62,.4); }

.chase-popup { position: absolute; left: 50%; top: 38%; transform: translate(-50%,-50%); text-align: center; animation: chaseIn .5s cubic-bezier(.16,.8,.3,1) both; }
.chase-title { font: 400 108px/0.82 var(--display); letter-spacing: 8px; color: #e8ded0; text-shadow: 9px 9px 0 #a20d16, 0 0 50px rgba(232,30,36,.35); }
.chase-sub { font: 700 10px/1 var(--mono); letter-spacing: 6px; color: #ff565c; margin-top: 18px; }
@keyframes chaseIn { from { opacity: 0; transform: translate(-50%,-50%) scale(1.3); filter: blur(8px); } to { opacity: 1; transform: translate(-50%,-50%) scale(1); filter: blur(0); } }

/* ---------- Screens ---------- */
.screen { position: absolute; inset: 0; z-index: 20; }
.menu-screen {
  background:
    radial-gradient(ellipse at 50% 30%, rgba(13, 41, 43, .13), transparent 55%),
    linear-gradient(180deg, rgba(2,7,8,.44) 0%, rgba(2,7,8,.72) 55%, rgba(2,7,8,.96) 100%);
  overflow: hidden;
}
.menu-noise {
  position: absolute; inset: 0; opacity: .17; pointer-events: none;
  background: repeating-linear-gradient(0deg, transparent 0 2px, rgba(255,255,255,.022) 2px 3px);
}
.menu-content {
  position: relative; z-index: 2; height: 100%; display: flex; flex-direction: column;
  align-items: center; justify-content: center; text-align: center; padding: 34px 22px 24px;
}
.eyebrow { display: flex; align-items: center; gap: 13px; font: 700 9px/1 var(--mono); letter-spacing: 4px; color: rgba(238,228,201,.64); margin-bottom: 19px; }
.eyebrow span { width: 36px; height: 1px; background: rgba(238,228,201,.37); }
.game-title { margin: 0; display: flex; flex-direction: column; align-items: center; filter: drop-shadow(0 18px 30px rgba(0,0,0,.7)); }
.title-small { font: 400 clamp(24px, 3.6vw, 44px)/.8 var(--display); letter-spacing: clamp(12px, 1.8vw, 22px); color: var(--red); text-shadow: 0 0 35px rgba(215,43,50,.28); transform: translateX(5px); }
.title-main {
  font: 400 clamp(72px, 13vw, 176px)/0.86 var(--display); letter-spacing: .015em;
  background: linear-gradient(180deg, #fff9e6 0%, #e8ddbf 46%, #a99a7b 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  text-shadow: 0 4px 0 rgba(0,0,0,.18); margin-top: -4px;
}
.title-tag {
  font: 700 clamp(9px, 1.2vw, 13px)/1 var(--mono); letter-spacing: clamp(5px, .8vw, 10px);
  color: #d4c8aa; border-top: 1px solid rgba(232,220,189,.34); border-bottom: 1px solid rgba(232,220,189,.34);
  padding: 9px 13px 8px; margin-top: 16px; transform: rotate(-1deg);
}
.menu-blurb { font: 15px/1.65 var(--mono); color: rgba(232,224,200,.62); margin: 26px 0 28px; letter-spacing: .3px; }
.menu-actions { display: flex; gap: 12px; align-items: center; }
.primary-button {
  position: relative; min-width: 196px; padding: 16px 34px 15px; border: 1px solid #ee4b50; cursor: pointer;
  font: 400 23px/1 var(--display); letter-spacing: 4px; color: #fff8e6;
  background: linear-gradient(180deg, #c2272c, #8f1218); box-shadow: 0 0 0 4px rgba(7,12,12,.55), 0 12px 28px rgba(0,0,0,.4), inset 0 1px 0 rgba(255,255,255,.22);
  transition: transform .18s, filter .18s, box-shadow .18s;
}
.primary-button:hover { transform: translateY(-2px); filter: brightness(1.14); box-shadow: 0 0 0 4px rgba(7,12,12,.55), 0 16px 35px rgba(0,0,0,.45), 0 0 32px rgba(210,30,36,.2); }
.primary-button:active { transform: translateY(1px); }
.primary-button.compact { min-width: 170px; padding: 13px 24px; font-size: 18px; letter-spacing: 3px; }
.ghost-button {
  min-width: 160px; padding: 15px 24px; background: rgba(8,14,14,.42); border: 1px solid rgba(232,222,196,.26);
  cursor: pointer; font: 700 10px/1 var(--mono); letter-spacing: 2px; color: rgba(242,234,212,.7);
  transition: all .18s; backdrop-filter: blur(6px);
}
.ghost-button:hover { border-color: rgba(242,234,212,.6); color: #fff7e2; background: rgba(21,32,31,.72); }
.ghost-button.compact { padding: 13px 20px; }
.menu-footer { position: absolute; left: 28px; right: 28px; bottom: max(20px, env(safe-area-inset-bottom)); display: flex; justify-content: space-between; font: 8px/1 var(--mono); letter-spacing: 1.3px; color: rgba(232,224,200,.32); }
.menu-sticker {
  position: absolute; top: 44%; font: 400 15px/0.92 var(--display); letter-spacing: 1px; text-align: center;
  color: #1b2624; background: #dccf9f; padding: 12px 10px; opacity: .42; box-shadow: 0 6px 14px rgba(0,0,0,.3);
  border: 1px dashed rgba(45,50,36,.3);
}
.sticker-left { left: 5%; transform: rotate(-8deg); }
.sticker-right { right: 5%; transform: rotate(6deg); background: #ddb7b4; }

.modal-screen { display: grid; place-items: center; background: rgba(2,6,7,.64); backdrop-filter: blur(8px); padding: 22px; }
.modal-card {
  width: min(620px, 94vw); padding: 38px; background:
    linear-gradient(135deg, rgba(17,28,27,.97), rgba(5,11,12,.98)),
    repeating-linear-gradient(90deg, transparent 0 70px, rgba(255,255,255,.02) 70px 71px);
  border: 1px solid rgba(230,219,187,.24); box-shadow: 0 30px 90px rgba(0,0,0,.6), inset 0 0 60px rgba(50,120,113,.05);
  position: relative;
}
.modal-card::before { content: "PLAYTIME CO."; position: absolute; right: 22px; top: 18px; font: 8px/1 var(--mono); letter-spacing: 2px; color: rgba(232,224,200,.22); }
.modal-kicker { font: 700 9px/1 var(--mono); letter-spacing: 3px; color: var(--red-hot); margin-bottom: 10px; }
.modal-card h2 { margin: 0 0 25px; font: 400 46px/1 var(--display); letter-spacing: 2px; color: #f3ead0; }
.control-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 13px 22px; margin-bottom: 25px; }
.control-grid > div { display: flex; align-items: center; gap: 11px; min-height: 35px; border-bottom: 1px solid rgba(233,222,192,.09); padding-bottom: 10px; }
.control-grid kbd { min-width: 80px; font: 700 9px/1 var(--mono); letter-spacing: .6px; color: #f1e8cd; text-align: center; padding: 7px 6px; border: 1px solid rgba(238,227,196,.28); background: rgba(238,227,196,.05); }
.control-grid span { font: 11px/1.3 var(--mono); color: rgba(232,224,200,.6); }
.modal-note { font: 13px/1.6 var(--mono); color: rgba(232,224,200,.63); margin: 0 0 26px; }
.modal-note em { color: #ff6f6f; font-style: normal; }
.pause-actions { display: flex; gap: 10px; flex-wrap: wrap; }

.story-screen { background: #030707; display: grid; place-items: center; cursor: pointer; }
.story-lines { width: min(780px, 86vw); text-align: center; }
.story-kicker { font: 700 10px/1 var(--mono); letter-spacing: 4px; color: var(--red-hot); margin-bottom: 28px; }
.story-text { min-height: 145px; font: 21px/1.7 var(--mono); letter-spacing: .5px; color: #e8dfc5; text-shadow: 0 0 30px rgba(0,0,0,.8); }
.story-text::after { content: "▌"; color: var(--red); animation: blink .7s steps(1) infinite; margin-left: 3px; }
@keyframes blink { 50% { opacity: 0; } }
.story-skip { position: absolute; bottom: 40px; left: 50%; transform: translateX(-50%); background: none; border: 0; cursor: pointer; font: 8px/1 var(--mono); letter-spacing: 2px; color: rgba(232,224,200,.3); }

.death-screen { background: radial-gradient(circle at 50% 40%, rgba(96,5,9,.9), #050202 70%); display: grid; place-items: center; overflow: hidden; }
.death-screen::before {
  content: ""; position: absolute; inset: -10%; background:
    radial-gradient(ellipse at 20% 35%, rgba(255,19,25,.11), transparent 22%),
    repeating-radial-gradient(circle at 50% 42%, transparent 0 20px, rgba(255,30,32,.015) 21px 22px);
  animation: deathPulse .7s ease-in-out infinite alternate;
}
@keyframes deathPulse { from { opacity: .5; transform: scale(1); } to { opacity: 1; transform: scale(1.05); } }
.death-inner { position: relative; text-align: center; }
.death-kicker { font: 700 9px/1 var(--mono); letter-spacing: 4px; color: #ff7a7a; margin-bottom: 16px; }
.death-inner h2 { font: 400 clamp(60px, 10vw, 118px)/.85 var(--display); letter-spacing: 3px; margin: 0 0 20px; color: #f4e6d2; text-shadow: 8px 8px 0 #4e0306; }
.death-inner p { font: 14px/1.5 var(--mono); color: rgba(246,230,217,.55); margin: 0 0 30px; }
.death-inner .ghost-button { margin-left: 8px; }

.win-screen { background: radial-gradient(circle at 50% 40%, #173837, #030707 72%); display: grid; place-items: center; overflow: hidden; }
.win-screen::before { content: ""; position: absolute; inset: 0; background: repeating-linear-gradient(105deg, transparent 0 120px, rgba(228,245,231,.018) 120px 121px); }
.win-inner { position: relative; text-align: center; padding: 30px; }
.win-kicker { font: 700 9px/1 var(--mono); letter-spacing: 5px; color: #78d8b3; margin-bottom: 16px; }
.win-inner h2 { font: 400 clamp(56px, 9vw, 108px)/.85 var(--display); letter-spacing: 4px; margin: 0 0 22px; color: #f5ecd5; text-shadow: 7px 7px 0 #19201e; }
.win-copy { font: 13px/1.8 var(--mono); color: rgba(239,230,207,.6); margin: 0 0 32px; }
.win-stats { display: flex; justify-content: center; gap: 52px; margin-bottom: 35px; }
.win-stats > div { display: flex; flex-direction: column; gap: 6px; }
.win-stats span { font: 400 33px/1 var(--display); letter-spacing: 2px; color: #f1e6c8; }
.win-stats small { font: 8px/1 var(--mono); letter-spacing: 1.6px; color: rgba(237,229,206,.4); }

.loading-screen {
  position: absolute; inset: 0; z-index: 50; background: #030707; display: flex; flex-direction: column;
  align-items: center; justify-content: center; transition: opacity .8s;
}
.loading-screen.done { opacity: 0; pointer-events: none; }
.loading-logo { font: 400 34px/1 var(--display); letter-spacing: 7px; color: #e9dfc3; margin-bottom: 24px; }
.loading-bar { width: 180px; height: 2px; background: rgba(255,255,255,.12); overflow: hidden; }
.loading-bar i { display: block; width: 45%; height: 100%; background: var(--red); animation: load 1.1s ease-in-out infinite; }
@keyframes load { 0% { transform: translateX(-110%); } 100% { transform: translateX(340%); } }
.loading-text { margin-top: 15px; font: 8px/1 var(--mono); letter-spacing: 2.5px; color: rgba(238,228,201,.36); }

/* ---------- Mobile ---------- */
.mobile-controls { position: absolute; inset: 0; z-index: 15; pointer-events: none; }
.joystick {
  position: absolute; left: max(22px, env(safe-area-inset-left)); bottom: max(26px, env(safe-area-inset-bottom));
  width: 118px; height: 118px; border-radius: 50%; border: 1px solid rgba(238,228,201,.22);
  background: radial-gradient(circle, rgba(10,21,21,.22), rgba(5,12,13,.54)); pointer-events: auto; touch-action: none;
  box-shadow: inset 0 0 22px rgba(0,0,0,.35);
}
.joystick-knob {
  position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; border-radius: 50%;
  transform: translate(-50%,-50%); background: rgba(219,211,187,.2); border: 1px solid rgba(240,232,207,.35);
  box-shadow: 0 4px 14px rgba(0,0,0,.4);
}
.mobile-actions { position: absolute; right: max(18px, env(safe-area-inset-right)); bottom: max(24px, env(safe-area-inset-bottom)); display: flex; align-items: flex-end; gap: 12px; pointer-events: auto; }
.mobile-btn {
  width: 70px; height: 70px; border-radius: 50%; border: 1px solid rgba(240,230,203,.32);
  background: rgba(7,15,16,.55); color: #f1e8d0; font: 700 9px/1 var(--mono); letter-spacing: 1px;
  backdrop-filter: blur(5px); touch-action: none;
}
