function makeGlove(color, wristColor) {
  const gloveMat = new THREE.MeshStandardMaterial({ color, roughness: .58, metalness: .02 });
  const cuffMat = new THREE.MeshStandardMaterial({ color: wristColor, roughness: .45, metalness: .18 });
  const dark = new THREE.MeshStandardMaterial({ color: 0x101719, roughness: .8 });
  const g = new THREE.Group();
  const cuff = new THREE.Mesh(new THREE.CylinderGeometry(.075, .09, .2, 10), cuffMat);
  cuff.rotation.x = Math.PI / 2;
  cuff.position.z = .07;
  g.add(cuff);
  const palm = new THREE.Mesh(new THREE.SphereGeometry(.082, 14, 10), gloveMat);
  palm.scale.set(1, .85, .95);
  palm.position.z = -.13;
  g.add(palm);
  const fingers = [];
  for (let i = 0; i < 4; i++) {
    const finger = new THREE.Group();
    finger.position.set((i - 1.5) * .038, -.005, -.19);
    const seg = new THREE.Mesh(new THREE.CapsuleGeometry(.018, .075, 4, 8), gloveMat);
    seg.rotation.x = Math.PI / 2;
    seg.position.z = -.045;
    finger.add(seg);
    const tip = new THREE.Mesh(new THREE.SphereGeometry(.019, 8, 6), gloveMat);
    tip.position.z = -.09;
    finger.add(tip);
    g.add(finger);
    fingers.push(finger);
  }
  const thumb = new THREE.Mesh(new THREE.CapsuleGeometry(.022, .07, 4, 8), gloveMat);
  thumb.rotation.z = 1.05;
  thumb.position.set(-.08, -.01, -.12);
  g.add(thumb);
  // forearm
  const arm = new THREE.Mesh(new THREE.CylinderGeometry(.046, .06, .55, 8), dark);
  arm.rotation.x = Math.PI / 2;
  arm.position.z = .35;
  g.add(arm);
  [cuff, palm, arm, thumb].forEach(m => { m.castShadow = true; });
  g.userData = { fingers, palm, cuff };
  return g;
}

export function createGrabPack() {
  const root = new THREE.Group();
  root.position.set(.38, -.33, -.58);
  root.rotation.set(-.22, -.18, -.1);
  const right = makeGlove(0x2d9dd0, 0xd7b43b);
  right.scale.setScalar(2.2);
  root.add(right);

  const left = new THREE.Group();
  left.position.set(-.92, -.04, -.03);
  left.rotation.set(.1, .18, .1);
  const l = makeGlove(0xc6433d, 0xb89d36);
  l.scale.setScalar(1.95);
  left.add(l);
  root.add(left);

  // grabpack pack back plate hints at lower screen
  const pack = new THREE.Group();
  pack.position.set(-.26, -.22, .28);
  const plate = new THREE.Mesh(new THREE.BoxGeometry(.44, .35, .06), new THREE.MeshStandardMaterial({ color: 0x222a2b, roughness: .72 }));
  plate.rotation.x = -.32;
  pack.add(plate);
  for (const s of [-1, 1]) {
    const coil = new THREE.Mesh(new THREE.TorusGeometry(.075, .018, 6, 14), new THREE.MeshStandardMaterial({ color: s < 0 ? 0xb53d39 : 0x2e91be, roughness: .5 }));
    coil.position.set(s * .12, .01, -.02);
    pack.add(coil);
  }
  root.add(pack);

  root.userData = { right, left, pack, active: 0, cooldown: 0, trigger: 0 };
  root.traverse(o => { if (o.isMesh) { o.castShadow = false; o.receiveShadow = false; } });
  return root;
}

export function updateGrabPack(pack, dt, grabbing = false) {
  const d = pack.userData;
  d.trigger = Math.max(0, d.trigger - dt * 2.8);
  const out = grabbing ? Math.sin(Math.min(1, d.trigger) * Math.PI) : 0;
  const breathe = performance.now() * .001;
  pack.position.x = .38 + Math.sin(breathe * .7) * .006;
  pack.position.y = -.33 + Math.sin(breathe * 1.05) * .008;
  pack.rotation.z = -.1 + Math.sin(breathe * .6) * .012;
  d.right.position.z = -.58 - out * .72;
  d.right.position.y = -.33 + out * .23;
  d.right.rotation.x = -.22 + out * .35;
  d.right.userData.fingers.forEach((f, i) => {
    f.rotation.x = out * .7 + Math.sin(breathe * 1.3 + i) * .03;
  });
  d.left.position.y = -.04 + Math.sin(breathe * .9 + 1) * .01;
}

export class Soundscape {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.ambient = null;
    this.alarm = null;
    this.chase = null;
    this.ready = false;
    this.noiseBuffer = null;
    this.reverb = null;
    this.stepTimer = 0;
    this.muted = false;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    const ctx = this.ctx;
    this.master = ctx.createGain();
    this.master.gain.value = .55;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 12;
    comp.ratio.value = 4;
    comp.attack.value = .01;
    comp.release.value = .3;
    this.master.connect(comp);
    comp.connect(ctx.destination);

    // simple generated room reverb
    const len = Math.floor(ctx.sampleRate * 1.9);
    const impulse = ctx.createBuffer(2, len, ctx.sampleRate);
    for (let ch = 0; ch < 2; ch++) {
      const data = impulse.getChannelData(ch);
      for (let i = 0; i < len; i++) {
        data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 2.7) * .32;
      }
    }
    this.reverb = ctx.createConvolver();
    this.reverb.buffer = impulse;
    const wet = ctx.createGain();
    wet.gain.value = .27;
    this.reverb.connect(wet);
    wet.connect(this.master);

    const noiseLen = Math.floor(ctx.sampleRate * 2);
    this.noiseBuffer = ctx.createBuffer(1, noiseLen, ctx.sampleRate);
    const noise = this.noiseBuffer.getChannelData(0);
    for (let i = 0; i < noiseLen; i++) noise[i] = Math.random() * 2 - 1;

    this.ready = true;
    this.startAmbient();
  }

  setMuted(value) {
    this.muted = value;
    if (this.master) this.master.gain.setTargetAtTime(value ? 0 : .55, this.ctx.currentTime, .08);
  }

  makeNoise(duration = .25, volume = .15, filterFreq = 700, type = 'bandpass') {
    if (!this.ready) return;
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = filterFreq;
    filter.Q.value = .8;
    const g = ctx.createGain();
    g.gain.setValueAtTime(volume, ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(.0001, ctx.currentTime + duration);
    src.connect(filter); filter.connect(g); g.connect(this.master);
    if (this.reverb) g.connect(this.reverb);
    src.start();
    src.stop(ctx.currentTime + duration + .02);
  }

  tone(freq = 440, duration = .2, volume = .08, type = 'sine', slide = 0, delay = 0) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const now = ctx.currentTime + delay;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, now);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), now + duration);
    g.gain.setValueAtTime(.0001, now);
    g.gain.exponentialRampToValueAtTime(volume, now + .012);
    g.gain.exponentialRampToValueAtTime(.0001, now + duration);
    o.connect(g); g.connect(this.master);
    if (this.reverb) g.connect(this.reverb);
    o.start(now); o.stop(now + duration + .04);
  }

  startAmbient() {
    if (!this.ready || this.ambient) return;
    const ctx = this.ctx;
    const bus = ctx.createGain();
    bus.gain.value = .13;
    bus.connect(this.master);
    if (this.reverb) bus.connect(this.reverb);

    // low factory drone
    const drone = ctx.createOscillator();
    drone.type = 'sawtooth';
    drone.frequency.value = 43;
    const drone2 = ctx.createOscillator();
    drone2.type = 'sine';
    drone2.frequency.value = 65.2;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 140;
    filter.Q.value = 2;
    const dg = ctx.createGain();
    dg.gain.value = .075;
    drone.connect(filter); drone2.connect(filter);
    filter.connect(dg); dg.connect(bus);
    drone.start(); drone2.start();

    // airy room noise
    const air = ctx.createBufferSource();
    air.buffer = this.noiseBuffer;
    air.loop = true;
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass'; bp.frequency.value = 340; bp.Q.value = .5;
    const ag = ctx.createGain(); ag.gain.value = .024;
    air.connect(bp); bp.connect(ag); ag.connect(bus);
    air.start();

    const lfo = ctx.createOscillator();
    lfo.frequency.value = .08;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = .018;
    lfo.connect(lfoGain); lfoGain.connect(dg.gain);
    lfo.start();

    this.ambient = { bus, drone, drone2, air, lfo };
  }

  stopAmbient() {
    if (!this.ambient) return;
    const a = this.ambient;
    try { a.bus.gain.setTargetAtTime(0, this.ctx.currentTime, .5); } catch { }
    setTimeout(() => {
      try { a.drone.stop(); a.drone2.stop(); a.air.stop(); a.lfo.stop(); } catch { }
    }, 1200);
    this.ambient = null;
  }

  footstep(sprint = false) {
    if (!this.ready) return;
    this.makeNoise(sprint ? .13 : .18, sprint ? .13 : .075, sprint ? 240 : 160, 'lowpass');
    this.tone(sprint ? 76 : 60, .08, .035, 'sine', -20);
  }

  pickup() {
    this.tone(620, .11, .06, 'sine', 220);
    this.tone(940, .18, .045, 'triangle', 260, .08);
  }

  tape() {
    this.tone(180, .18, .05, 'square', 20);
    this.makeNoise(.1, .04, 1500, 'highpass');
    this.tone(440, .4, .035, 'sine', -120, .12);
  }

  interact() {
    this.tone(230, .06, .04, 'square', 90);
    this.makeNoise(.06, .025, 2000, 'highpass');
  }

  denied() {
    this.tone(130, .15, .07, 'square', -20);
    this.tone(110, .2, .05, 'square', -20, .13);
  }

  insertFuse() {
    this.tone(300, .12, .09, 'square', 340);
    this.makeNoise(.09, .07, 1200, 'bandpass');
    this.tone(1100, .3, .035, 'sine', -150, .1);
  }

  powerOn() {
    if (!this.ready) return;
    this.makeNoise(.7, .11, 400, 'lowpass');
    const notes = [110, 164.8, 220, 329.6];
    notes.forEach((n, i) => this.tone(n, .8, .05, 'triangle', 0, i * .11));
    this.tone(55, 1.4, .13, 'sawtooth', 20, 0);
    setTimeout(() => this.startPowerHum(), 300);
    setTimeout(() => this.stopAlarm(), 400);
  }

  startPowerHum() {
    if (!this.ready || this.powerHum) return;
    const ctx = this.ctx;
    const o = ctx.createOscillator();
    o.type = 'sawtooth'; o.frequency.value = 100;
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 260;
    const g = ctx.createGain(); g.gain.value = 0;
    g.gain.setTargetAtTime(.035, ctx.currentTime, 1.2);
    o.connect(f); f.connect(g); g.connect(this.master);
    if (this.reverb) g.connect(this.reverb);
    o.start();
    this.powerHum = { o, g, f };
  }

  glassBreak() {
    if (!this.ready) return;
    this.makeNoise(.55, .18, 3800, 'highpass');
    for (let i = 0; i < 7; i++) this.tone(1200 + Math.random() * 2400, .1 + Math.random() * .2, .018, 'triangle', -400, i * .025);
  }

  door(intensity = 1) {
    this.makeNoise(.7, .12 * intensity, 190, 'lowpass');
    this.tone(52, .45, .1 * intensity, 'sawtooth', -18);
    this.tone(38, .7, .06 * intensity, 'sine', -10);
  }

  roar() {
    if (!this.ready) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    const g = ctx.createGain();
    g.gain.setValueAtTime(.0001, now);
    g.gain.exponentialRampToValueAtTime(.24, now + .1);
    g.gain.exponentialRampToValueAtTime(.0001, now + 1.8);
    g.connect(this.master); if (this.reverb) g.connect(this.reverb);
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass'; filter.frequency.setValueAtTime(400, now);
    filter.frequency.exponentialRampToValueAtTime(1200, now + .5);
    filter.connect(g);
    for (const detune of [0, 7, -5]) {
      const o = ctx.createOscillator();
      o.type = 'sawtooth';
      o.frequency.setValueAtTime(82 + detune, now);
      o.frequency.exponentialRampToValueAtTime(46 + detune, now + 1.4);
      o.connect(filter); o.start(now); o.stop(now + 1.85);
    }
    const growl = ctx.createBufferSource();
    growl.buffer = this.noiseBuffer;
    const nf = ctx.createBiquadFilter(); nf.type = 'bandpass'; nf.frequency.value = 320;
    const ng = ctx.createGain(); ng.gain.value = .15;
    growl.connect(nf); nf.connect(ng); ng.connect(g);
    growl.start(now); growl.stop(now + 1.8);
  }

  startAlarm() {
    if (!this.ready || this.alarm) return;
    const ctx = this.ctx;
    const bus = ctx.createGain();
    bus.gain.value = .0001;
    bus.gain.setTargetAtTime(.055, ctx.currentTime, .3);
    bus.connect(this.master);
    if (this.reverb) bus.connect(this.reverb);
    const o = ctx.createOscillator();
    o.type = 'sawtooth'; o.frequency.value = 540;
    const lfo = ctx.createOscillator();
    lfo.type = 'sine'; lfo.frequency.value = .62;
    const depth = ctx.createGain(); depth.gain.value = 190;
    lfo.connect(depth); depth.connect(o.frequency);
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 1500;
    o.connect(f); f.connect(bus);
    o.start(); lfo.start();
    this.alarm = { bus, o, lfo };
  }

  stopAlarm() {
    if (!this.alarm) return;
    const a = this.alarm;
    try { a.bus.gain.setTargetAtTime(0, this.ctx.currentTime, .5); } catch { }
    setTimeout(() => { try { a.o.stop(); a.lfo.stop(); } catch { } }, 1600);
    this.alarm = null;
  }

  startChase() {
    if (!this.ready || this.chase) return;
    this.startAlarm();
    const ctx = this.ctx;
    const bus = ctx.createGain();
    bus.gain.value = .0001;
    bus.gain.setTargetAtTime(.055, ctx.currentTime, .5);
    bus.connect(this.master);
    if (this.reverb) bus.connect(this.reverb);

    const pulse = ctx.createOscillator();
    pulse.type = 'triangle'; pulse.frequency.value = 55;
    const lfo = ctx.createOscillator();
    lfo.type = 'square'; lfo.frequency.value = 3.1;
    const lg = ctx.createGain(); lg.gain.value = .8;
    const pg = ctx.createGain(); pg.gain.value = .5;
    lfo.connect(lg); lg.connect(pg.gain);
    pulse.connect(pg); pg.connect(bus);
    pulse.start(); lfo.start();

    const high = ctx.createOscillator();
    high.type = 'sawtooth'; high.frequency.value = 146.8;
    const hg = ctx.createGain(); hg.gain.value = .009;
    high.connect(hg); hg.connect(bus);
    high.start();
    this.chase = { bus, pulse, high, lfo };
  }

  stopChase() {
    this.stopAlarm();
    if (!this.chase) return;
    const c = this.chase;
    try { c.bus.gain.setTargetAtTime(0, this.ctx.currentTime, .4); } catch { }
    setTimeout(() => { try { c.pulse.stop(); c.high.stop(); c.lfo.stop(); } catch { } }, 1000);
    this.chase = null;
  }

  heartbeat(intensity = 1) {
    this.tone(52, .11, .075 * intensity, 'sine', -12);
    this.tone(44, .16, .05 * intensity, 'sine', -8, .18);
  }

  whisper() {
    this.makeNoise(.8, .022, 900, 'bandpass');
    this.tone(310, 1.2, .012, 'sine', -60);
  }

  win() {
    if (!this.ready) return;
    this.stopChase();
    const notes = [220, 277.2, 329.6, 440, 554.4];
    notes.forEach((n, i) => this.tone(n, 1.5, .04, 'sine', 0, i * .18));
    this.tone(110, 3, .07, 'triangle', 0, 0);
  }

  lose() {
    if (!this.ready) return;
    this.stopChase();
    this.roar();
    this.makeNoise(1.2, .22, 240, 'lowpass');
    this.tone(70, 1.6, .13, 'sawtooth', -30);
  }
}

import * as THREE from 'three';
import {
  concreteTexture, tileWallTexture, carpetTexture, metalTexture, woodTexture,
  hazardTexture, signTexture, toyBoxTexture, paperTexture, radialSprite
} from './textures.js';

const PI = Math.PI;

function addBox(parent, w, h, d, mat, x, y, z, ry = 0, cast = true, receive = true) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.position.set(x, y, z);
  m.rotation.y = ry;
  m.castShadow = cast;
  m.receiveShadow = receive;
  parent.add(m);
  return m;
}

function addCyl(parent, rt, rb, h, mat, x, y, z, seg = 12, rx = 0, rz = 0) {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, seg), mat);
  m.position.set(x, y, z);
  m.rotation.x = rx;
  m.rotation.z = rz;
  m.castShadow = true;
  m.receiveShadow = true;
  parent.add(m);
  return m;
}

function plane(parent, w, h, mat, x, y, z, ry = 0, rx = 0) {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), mat);
  m.position.set(x, y, z);
  m.rotation.set(rx, ry, 0);
  m.receiveShadow = true;
  parent.add(m);
  return m;
}

function floorPlane(parent, x1, x2, z1, z2, mat, y = .015) {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(x2 - x1, z2 - z1), mat);
  m.rotation.x = -PI / 2;
  m.position.set((x1 + x2) / 2, y, (z1 + z2) / 2);
  m.receiveShadow = true;
  parent.add(m);
  return m;
}

function ceilingPlane(parent, x1, x2, z1, z2, mat, y) {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(x2 - x1, z2 - z1), mat);
  m.rotation.x = PI / 2;
  m.position.set((x1 + x2) / 2, y, (z1 + z2) / 2);
  m.receiveShadow = true;
  parent.add(m);
  return m;
}

function makeSign(parent, texture, w, h, x, y, z, ry = 0, brightness = 1) {
  const mat = new THREE.MeshBasicMaterial({ map: texture, color: new THREE.Color(brightness, brightness, brightness), transparent: false });
  return plane(parent, w, h, mat, x, y, z, ry);
}

function cloneTex(tex, rx, ry) {
  const t = tex.clone();
  t.needsUpdate = true;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(rx, ry);
  return t;
}

function matWith(tex, color = 0xffffff, roughness = .9, metalness = 0) {
  return new THREE.MeshStandardMaterial({ map: tex, color, roughness, metalness });
}

function makeFuse(color = 0x54e3a9) {
  const g = new THREE.Group();
  const capMat = new THREE.MeshStandardMaterial({ color: 0x9b9d90, roughness: .35, metalness: .75 });
  const glassMat = new THREE.MeshStandardMaterial({
    color: 0xd7fff0, emissive: color, emissiveIntensity: 2.4, roughness: .15, metalness: .1,
    transparent: true, opacity: .9
  });
  addCyl(g, .075, .075, .15, capMat, 0, -.16, 0, 12);
  addCyl(g, .075, .075, .15, capMat, 0, .16, 0, 12);
  const glass = addCyl(g, .085, .085, .25, glassMat, 0, 0, 0, 14);
  glass.userData.isGlass = true;
  addCyl(g, .095, .095, .025, capMat, 0, .105, 0, 12);
  addCyl(g, .095, .095, .025, capMat, 0, -.105, 0, 12);
  const light = new THREE.PointLight(color, 3.5, 3.2, 2);
  g.add(light);
  g.userData.glow = light;
  return g;
}

function makeTape() {
  const g = new THREE.Group();
  const shell = new THREE.MeshStandardMaterial({ color: 0x1c1e1c, roughness: .58 });
  const label = new THREE.MeshStandardMaterial({ color: 0xd7ccb0, roughness: .88 });
  const reelMat = new THREE.MeshStandardMaterial({ color: 0x9b9a8d, roughness: .5 });
  addBox(g, .44, .05, .28, shell, 0, 0, 0);
  addBox(g, .3, .052, .18, label, 0, .003, 0);
  for (const s of [-1, 1]) {
    const reel = addCyl(g, .052, .052, .06, reelMat, s * .09, .02, 0, 12);
    reel.rotation.x = PI / 2;
    addCyl(g, .018, .018, .065, shell, s * .09, .025, 0, 8).rotation.x = PI / 2;
  }
  addBox(g, .06, .053, .1, shell, 0, .006, -.06);
  const glow = new THREE.PointLight(0xf0c24b, 1.5, 2.2, 2);
  g.add(glow);
  return g;
}

function makeCrate(parent, x, z, w = 1.1, h = 1.0, d = 1.1, color = 0x65442c, ry = 0, colliders = []) {
  const woodMat = new THREE.MeshStandardMaterial({ color, roughness: .9 });
  const g = new THREE.Group();
  g.position.set(x, h / 2, z);
  g.rotation.y = ry;
  const body = addBox(g, w, h, d, woodMat, 0, 0, 0);
  const trim = new THREE.MeshStandardMaterial({ color: 0x3b2a1d, roughness: .8 });
  addBox(g, w + .03, .08, d + .03, trim, 0, h * .38, 0);
  addBox(g, w + .03, .08, d + .03, trim, 0, -h * .38, 0);
  addBox(g, w + .04, .1, .06, trim, 0, 0, d / 2 + .02);
  parent.add(g);
  colliders.push({ x1: x - w / 2 - .1, x2: x + w / 2 + .1, z1: z - d / 2 - .1, z2: z + d / 2 + .1 });
  return g;
}

function makeBarrel(parent, x, z, color = 0x394b42, colliders = []) {
  const mat = new THREE.MeshStandardMaterial({ color, roughness: .55, metalness: .45 });
  const g = new THREE.Group();
  g.position.set(x, 0, z);
  const b = addCyl(g, .33, .33, 1.0, mat, 0, .5, 0, 16);
  b.castShadow = true;
  const band = new THREE.MeshStandardMaterial({ color: 0x161b1a, roughness: .5, metalness: .5 });
  addCyl(g, .35, .35, .06, band, 0, .22, 0, 16);
  addCyl(g, .35, .35, .06, band, 0, .78, 0, 16);
  parent.add(g);
  colliders.push({ x1: x - .42, x2: x + .42, z1: z - .42, z2: z + .42 });
  return g;
}

function makeRope(parent, points, color = 0x8c1d25) {
  const curve = new THREE.CatmullRomCurve3(points);
  const geo = new THREE.TubeGeometry(curve, 18, .022, 5, false);
  const m = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ color, roughness: .8 }));
  parent.add(m);
  return m;
}

function makeStanchion(parent, x, z, colliders = []) {
  const gold = new THREE.MeshStandardMaterial({ color: 0xb59a55, roughness: .3, metalness: .7 });
  const dark = new THREE.MeshStandardMaterial({ color: 0x3f3124, roughness: .6 });
  addCyl(parent, .15, .18, .05, dark, x, .025, z, 16);
  addCyl(parent, .036, .045, .9, gold, x, .48, z, 10);
  const top = new THREE.Mesh(new THREE.SphereGeometry(.075, 12, 10), gold);
  top.position.set(x, .96, z);
  parent.add(top);
  return { x, z, topY: 1 };
}

export function buildWorld(scene) {
  const root = new THREE.Group();
  root.name = 'PlaytimeCo';
  scene.add(root);

  const colliders = [];
