    { x1: 14.1, x2: 15.4, z1: 17.55, z2: 21.45, id: 'storage-door' },
    { x1: 15.0, x2: 24.1, z1: 13.8, z2: 24.25, id: 'storage' },
    { x1: -3.35, x2: 3.35, z1: 1.82, z2: 4.1, id: 'arch' },
    { x1: -14.1, x2: 14.1, z1: -21.7, z2: 1.92, id: 'display' },
