import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', e => console.log('PAGEERROR:', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE:', m.text()); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1200);
console.log('quality', await page.evaluate(() => window.__pop?.quality));
await page.evaluate(() => document.getElementById('play-button').click());
await page.waitForTimeout(800);
console.log('state', await page.evaluate(() => window.__pop?.state));
const fps = await page.evaluate(() => new Promise(res => {
