import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

async function run(variant) {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  page.on('pageerror', e => console.log('PAGEERROR:', e.message));
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
  await page.waitForTimeout(900);
  await page.evaluate(() => document.getElementById('play-button').click());
  await page.waitForTimeout(400);
  const out = await page.evaluate(async (variant) => {
    const hide = sel => { const el = document.querySelector(sel); if (el) el.style.display = 'none'; };
    if (variant === 'fx') hide('.fx-layer');
    if (variant === 'grain') hide('.grain');
    if (variant === 'vignette') hide('.vignette');
    if (variant === 'hud') hide('#hud');
    if (variant === 'all') { hide('.fx-layer'); hide('#hud'); }
    if (variant === 'canvas') document.getElementById('game').style.visibility = 'hidden';
    // let it settle
    await new Promise(r => setTimeout(r, 300));
    const fps = await new Promise(res => {
      const t = performance.now(); let n = 0;
      function f() { n++; if (performance.now() - t < 1500) requestAnimationFrame(f); else res(n / ((performance.now() - t) / 1000)); }
      requestAnimationFrame(f);
    });
    // time one forced render
    const { renderer, scene, camera } = window.__pop;
    const gl = renderer.getContext();
    const t = performance.now();
    renderer.render(scene, camera); gl.finish();
    const renderMs = performance.now() - t;
    return { fps: Math.round(fps * 10) / 10, renderMs: Math.round(renderMs) };
  }, variant);
  console.log(variant.padEnd(10), out);
  await browser.close();
}

for (const v of ['baseline', 'grain', 'vignette', 'fx', 'hud', 'all', 'canvas']) await run(v);

