  const out = await page.evaluate(async (bufferScale) => {
    const c = document.getElementById('c');
    c.width = innerWidth * bufferScale;
    c.height = innerHeight * bufferScale;
    const gl = c.getContext('webgl2', { antialias: false, preserveDrawingBuffer: false });
    const fps = await new Promise(res => {
      const t = performance.now(); let n = 0;
      function f() {
        gl.clearColor(Math.random(), 0, 0, 1); gl.clear(gl.COLOR_BUFFER_BIT);
