import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', e => console.log('PAGEERROR:', e.message));
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 90000 });
await page.waitForTimeout(1200);
await page.evaluate(() => document.getElementById('play-button').click());
await page.waitForTimeout(2000);

async function measure(label, ms = 3000) {
  const r = await page.evaluate(async (ms) => {
    const t = performance.now(); let n = 0;
    await new Promise(res => {
      function f() { n++; if (performance.now() - t < ms) requestAnimationFrame(f); else res(); }
      requestAnimationFrame(f);
    });
    return { frames: n, ms: Math.round(performance.now() - t) };
  }, ms);
  console.log(label.padEnd(22), r, 'fps', (r.frames / (r.ms / 1000)).toFixed(2));
}

await measure('baseline');
await page.evaluate(() => { document.querySelector('.grain').style.display = 'none'; });
